INSERT INTO `chinese_documents` VALUES (1,'HSK 4 Reading Practice','Bài đọc luyện thi HSK 4','pdf','/documents/hsk4-reading.pdf','intermediate',4,'reading',350,NULL,'/images/giao-trinh-han-ngu-1_1-1748617449484.jpg',1,1.00,'2025-05-20 15:59:51','2025-05-30 22:08:37'),(32,'Giáo trình luyện đọc tiếng Hán cấp tốc – nhập môn 汉语阅读速成入门篇','<p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; color: rgb(0, 0, 0); font-family: Arial, Helvetica, sans-serif; font-size: 14.3px; text-align: justify;\"><span style=\"font-size: 12pt;\">Phần đọc trong tiếng Hán có lẽ là là phần thi mất nhiều thời gian nhất và đòi hỏi những kỹ năng đọc hiểu và dịch. Biết được nỗi lo lắng của bạn với môn đọc vậy nên hôm nay, Tiếng Trung Thượng Hải sẽ giới thiệu đến các bạn một quyển sách hỗ trợ khả năng đọc hiểu vô cùng hiệu quả, được xuất bản tại Đại Học Ngôn Ngữ Bắc Kinh. Đó chính là quyển ”&nbsp;<span style=\"font-weight: 600;\">Giáo trình luyện đọc tiếng Hán cấp tốc – Nhập môn 汉语阅读速成入门篇</span>&nbsp;” –&nbsp;<span style=\"font-weight: 600;\">(Short-term reading Chinese Threshold)</span>.</span></p><p style=\"margin-right: 0px; margin-bottom: 20px; margin-left: 0px; color: rgb(0, 0, 0); font-family: Arial, Helvetica, sans-serif; font-size: 14.3px; text-align: justify;\"><span style=\"font-size: 12pt;\"><span style=\"font-weight: 600;\">Download tại link bên dưới<img class=\"emoji\" draggable=\"false\" src=\"https://s.w.org/images/core/emoji/12.0.0-1/svg/1f447.svg\" alt=\"?\" style=\"max-width: 100%; vertical-align: -0.1em !important; border-width: initial !important; border-color: initial !important; border-image: initial !important; height: 1em !important; display: inline !important; box-shadow: none !important; width: 1em !important; margin: 0px 0.07em !important; background: none !important; padding: 0px !important;\"><img class=\"emoji\" draggable=\"false\" src=\"https://s.w.org/images/core/emoji/12.0.0-1/svg/1f447.svg\" alt=\"?\" style=\"max-width: 100%; vertical-align: -0.1em 