DROP TABLE IF EXISTS `grammar`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `grammar` (
  `grammar_id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(100) NOT NULL,
  `structure` text NOT NULL,
  `explanation` text,
  `example_chinese` text,
  `example_pinyin` text,
  `example_english` text,
  `difficulty_level` enum('beginner','intermediate','advanced') DEFAULT NULL,
  `hsk_level` int DEFAULT NULL,
  PRIMARY KEY (`grammar_id`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Bảng các điểm ngữ pháp tiếng Trung';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `grammar`
--

LOCK TABLES `grammar` WRITE;
/*!40000 ALTER TABLE `grammar` DISABLE KEYS */;
INSERT INTO `grammar` VALUES (1,'是...的','Subject + 是 + Verb + 的','Used to emphasize past actions or facts.','我是昨天来的。','Wǒ shì zuótiān lái de.','I came yesterday.','intermediate',4),(2,'一边...一边...','Subject + 一边 + Verb1 + 一边 + Verb2','Used to indicate two simultaneous actions.','他一边吃饭一边看电视。','Tā yībiān chīfàn yībiān kàn diànshì.','He eats while watching TV.','beginner',3),(3,'是...的','Subject + 是 + Verb + 的','Used to emphasize past actions or facts.','我是昨天来的。','Wǒ shì zuótiān lái de.','I came yesterday.','intermediate',4),(4,'一边...一边...','Subject + 一边 + Verb1 + 一边 + Verb2','Used to indicate two simultaneous actions.','他一边吃饭一边看电视。','Tā yībiān chīfàn yībiān kàn diànshì.','He eats while watching TV.','beginner',3),(5,'Câu khẳng định với 是','Subject + 是 + Object','Cấu trúc cơ bản để nói \'A là B\'','我是学生。','Wǒ shì xuéshēng.','I am a student.','beginner',1),(6,'Câu hỏi với 吗','Statement + 吗','Thêm 吗 vào cuối câu để tạo câu hỏi','你好吗？','Nǐ hǎo ma?','How are you?','beginner',1),(7,'Câu phủ định với 不','Subject + 不 + Verb','Thêm 不 trước động từ để phủ định','我不是老师。','Wǒ bù shì lǎoshī.','I am not a teacher.','beginner',1),(8,'Đại từ nhân xưng','我/你/他/她','Các đại từ nhân xưng cơ bản','他是医生。','Tā shì yīshēng.','He is a doctor.','beginner',1),(9,'Số nhiều với 们','Pronoun + 们','Thêm 们 để chỉ số nhiều','我们是朋友。','Wǒmen shì péngyǒu.','We are friends.','beginner',1),(10,'Câu với 有','Subject + 有 + Object','Cấu trúc để nói \'có\'','我有书。','Wǒ yǒu shū.','I have books.','beginner',1),(11,'Câu hỏi với 什么','什么 + Noun','Dùng để hỏi \'cái gì\'','这是什么？','Zhè shì shénme?','What is this?','beginner',1),(12,'Câu với 在','Subject + 在 + Location','Cấu trúc để nói \'ở đâu\'','我在学校。','Wǒ zài xuéxiào.','I am at school.','beginner',1),(13,'Câu với 喜欢','Subject + 喜欢 + Object','Cấu trúc để nói \'thích\'','我喜欢中文。','Wǒ xǐhuān zhōngwén.','I like Chinese.','beginner',1),(14,'Câu với 学习','Subject + 学习 + Object','Cấu trúc để nói \'học\'','我学习中文。','Wǒ xuéxí zhōngwén.','I study Chinese.','beginner',1),(15,'Câu với 工作','Subject + 工作','Cấu trúc để nói \'làm việc\'','我工作。','Wǒ gōngzuò.','I work.','beginner',1),(16,'Câu với 吃饭','Subject + 吃饭','Cấu trúc để nói \'ăn cơm\'','我吃饭。','Wǒ chīfàn.','I eat.','beginner',1),(17,'Câu với 睡觉','Subject + 睡觉','Cấu trúc để nói \'ngủ\'','我睡觉。','Wǒ shuìjiào.','I sleep.','beginner',1),(18,'Câu với 看','Subject + 看 + Object','Cấu trúc để nói \'xem\'','我看电影。','Wǒ kàn diànyǐng.','I watch movies.','beginner',1),(19,'Câu với 听','Subject + 听 + Object','Cấu trúc để nói \'nghe\'','我听音乐。','Wǒ tīng yīnyuè.','I listen to music.','beginner',1);
/*!40000 ALTER TABLE `grammar` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `hskquestions`
--

DROP TABLE IF EXISTS `hskquestions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hskquestions` (
  `question_id` int NOT NULL AUTO_INCREMENT,
  `test_id` int NOT NULL,
  `question_type` enum('listening','reading','writing','multiple_choice','fill_blank','matching','true_false','ordering','rewrite') NOT NULL,
  `question_text` text,
  `audio_url` varchar(255) DEFAULT NULL,
  `image_url` varchar(255) DEFAULT NULL,
  `options` json DEFAULT NULL,
  `correct_answer` text NOT NULL,
  `explanation` text,
  `difficulty_level` enum('easy','medium','hard') DEFAULT NULL,
  `points` int NOT NULL DEFAULT '1',
  `order_in_test` int NOT NULL DEFAULT '0',
  `matching_pairs` json DEFAULT NULL,
  `ordering_items` json DEFAULT NULL,
  `rewrite_instruction` text,
  `skill_type` enum('listening','reading','writing') NOT NULL DEFAULT 'reading',
  PRIMARY KEY (`question_id`),
  KEY `test_id` (`test_id`),
  KEY `ix_hskq_test_order` (`test_id`,`order_in_test`),
  CONSTRAINT `hskquestions_ibfk_1` FOREIGN KEY (`test_id`) REFERENCES `hsktests` (`test_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=137 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Bảng câu hỏi trong đề thi HSK';
/*!40101 SET character_set_client = @saved_cs_client */;

