INSERT INTO `hskquestions` VALUES (54,1,'multiple_choice','Chọn từ đúng để điền vào chỗ trống: 我每天_____去学校。',NULL,NULL,'[\"走\", \"跑\", \"飞\", \"游\"]','A','Đi bộ là cách di chuyển phổ biến nhất để đến trường','easy',1,8,NULL,NULL,NULL,'reading'),(55,1,'multiple_choice','Từ nào có nghĩa là \"cảm ơn\"?',NULL,NULL,'[\"你好\", \"谢谢\", \"再见\", \"对不起\"]','B','谢谢 (xièxie) có nghĩa là \"cảm ơn\"','easy',1,9,NULL,NULL,NULL,'reading'),(56,1,'multiple_choice','Chọn từ đồng nghĩa với \"大\":',NULL,NULL,'[\"小\", \"高\", \"长\", \"宽\"]','B','大 và 高 đều có thể chỉ kích thước lớn','medium',2,10,NULL,NULL,NULL,'reading'),(57,1,'fill_blank','我(1)每天(2)去学校(3)学习。',NULL,NULL,'[[\"喜欢\", \"讨厌\", \"需要\", \"想要\"], [\"早上\", \"晚上\", \"中午\", \"下午\"], [\"中文\", \"英文\", \"数学\", \"历史\"]]','A,A,A','Điền các từ phù hợp về thói quen học tập','medium',2,11,NULL,NULL,NULL,'reading'),(58,1,'fill_blank','这个(1)很(2)，我很(3)它。',NULL,NULL,'[[\"书\", \"笔\", \"桌子\", \"椅子\"], [\"新\", \"旧\", \"大\", \"小\"], [\"喜欢\", \"讨厌\", \"需要\", \"想要\"]]','A,A,A','Điền từ để tạo câu hoàn chỉnh về sự vật','easy',1,12,NULL,NULL,NULL,'reading'),(59,1,'matching','Ghép nối từ tiếng Trung với nghĩa tiếng Việt:',NULL,NULL,NULL,'A-1,B-2,C-3,D-4','Ghép nối các từ chào hỏi cơ bản','easy',2,13,'[{\"left\": \"你好\", \"right\": \"Xin chào\"}, {\"left\": \"谢谢\", \"right\": \"Cảm ơn\"}, {\"left\": \"再见\", \"right\": \"Tạm biệt\"}, {\"left\": \"对不起\", \"right\": \"Xin lỗi\"}]',NULL,NULL,'reading'),(60,1,'matching','Ghép nối từ với nghĩa tương ứng:',NULL,NULL,NULL,'A-1,B-2,C-3,D-4','Ghép nối từ chỉ kích thước','easy',2,14,'[{\"left\": \"大\", \"right\": \"Lớn\"}, {\"left\": \"小\", \"right\": \"Nhỏ\"}, {\"left\": \"高\", \"right\": \"Cao\"}, {\"left\": \"矮\", \"right\": \"Thấp\"}]',NULL,NULL,'reading'),(61,1,'true_false','你好 có nghĩa là \"cảm ơn\"',NULL,NULL,NULL,'false','你好 có nghĩa là \"xin chào\", không phải \"cảm ơn\"','easy',1,15,NULL,NULL,NULL,'reading'),(62,1,'true_false','Trong tiếng Trung, 大 có nghĩa là \"lớn\"',NULL,NULL,NULL,'true','大 (dà) có nghĩa là \"lớn\"','easy',1,16,NULL,NULL,NULL,'reading'),(63,1,'ordering','Sắp xếp các từ theo thứ tự đúng để tạo câu hoàn chỉnh:',NULL,NULL,NULL,'1,2,3,4','Thứ tự đúng: 我每天去学校 (Tôi mỗi ngày đi trường)','medium',2,17,NULL,'[\"我\", \"每天\", \"去\", \"学校\"]',NULL,'reading'),(64,1,'ordering','Sắp xếp các từ để tạo câu chào hỏi:',NULL,NULL,NULL,'1,2,3,4,5','Thứ tự đúng: 你好，我是学生 (Xin chào, tôi là học sinh)','medium',2,18,NULL,'[\"你好\", \"，\", \"我\", \"是\", \"学生\"]',NULL,'reading'),(65,1,'rewrite','Viết lại câu sau bằng cách sử dụng từ đồng nghĩa: 我很高兴。',NULL,NULL,NULL,'我很开心。','Thay 高兴 bằng 开心 để diễn tả sự vui vẻ','medium',2,19,NULL,NULL,'Sử dụng từ đồng nghĩa để viết lại câu','writing'),(66,1,'rewrite','Viết lại câu sau ở dạng phủ định: 我喜欢学习中文。',NULL,NULL,NULL,'我不喜欢学习中文。','Thêm 不 để tạo câu phủ định','medium',2,20,NULL,NULL,'Chuyển câu khẳng định thành phủ định','writing'),(67,1,'multiple_choice','Nghe và chọn từ đúng:','https://example.com/audio/hello.mp3',NULL,'[\"你好\", \"谢谢\", \"再见\", \"对不起\"]','A','Audio phát âm từ \"你好\" (xin chào)','easy',2,21,NULL,NULL,NULL,'listening'),(68,1,'multiple_choice','Nghe và chọn câu đúng:','https://example.com/audio/thank_you.mp3',NULL,'[\"谢谢\", \"不客气\", \"再见\", \"你好\"]','A','Audio phát âm từ \"谢谢\" (cảm ơn)','easy',2,22,NULL,NULL,NULL,'listening'),(69,1,'multiple_choice','Nhìn hình và chọn từ đúng:',NULL,'https://example.com/images/apple.jpg','[\"苹果\", \"香蕉\", \"橙子\", \"葡萄\"]','A','Hình ảnh quả táo - 苹果','easy',1,23,NULL,NULL,NULL,'reading'),(70,1,'multiple_choice','Nhìn hình và chọn từ đúng:',NULL,'https://example.com/images/book.jpg','[\"书\", \"笔\", \"纸\", \"桌子\"]','A','Hình ảnh quyển sách - 书','easy',1,24,NULL,NULL,NULL,'reading'),(71,1,'multiple_choice','Chọn từ phù hợp để điền vào chỗ trống: 他_____了三个小时才完成作业。',NULL,NULL,'[\"工作\", \"学习\", \"休息\", \"睡觉\"]','B','学习 (học tập) phù hợp với ngữ cảnh làm bài tập','hard',3,25,NULL,NULL,NULL,'reading'),(72,1,'multiple_choice','Từ nào có nghĩa gần nhất với \"努力\"?',NULL,NULL,'[\"聪明\", \"努力\", \"快乐\", \"安静\"]','B','努力 có nghĩa là \"chăm chỉ, cố gắng\"','hard',3,26,NULL,NULL,NULL,'reading'),(73,1,'fill_blank','他(1)很(2)，所以(3)很好。',NULL,NULL,'[[\"学习\", \"工作\", \"休息\", \"睡觉\"], [\"努力\", \"聪明\", \"快乐\", \"安静\"], [\"成绩\", \"工作\", \"生活\", \"身体\"]]','A,A,C','Điền từ để tạo câu về việc học tập chăm chỉ','hard',3,27,NULL,NULL,NULL,'reading'),(81,3,'ordering','sắp xép câu hoi',NULL,NULL,'[]','1,2',NULL,'easy',1,2,NULL,NULL,NULL,'listening'),(82,3,'ordering','xếp câu',NULL,NULL,'[]','1,2,3,4','sdfsd','easy',1,1,NULL,NULL,NULL,'listening'),(84,3,'matching','ghep2',NULL,NULL,'[]','A-1,B-2',NULL,'easy',1,3,'[{\"left\": \"tôi là ban\", \"right\": \"1\"}, {\"left\": \"ban là toi\", \"right\": \"2\"}]',NULL,NULL,'listening'),(85,3,'ordering','xapxep',NULL,NULL,'[]','1,2,3,4',NULL,'easy',1,4,NULL,'[\"một\", \"hai\", \"ba\", \"bốn\"]',NULL,'listening'),(86,3,'matching','ádasd',NULL,NULL,'[]','A-1,B-2','ád','easy',1,5,'[{\"left\": \"ưedfsd\", \"right\": \"sdfsdf\"}, {\"left\": \"ád\", \"right\": \"ád\"}]',NULL,NULL,'listening'),(94,4,'true_false','Thí sinh hãy nhìn ảnh và phán đoán đúng sai ','hsk-audio/mnwqulbermid3pltrmn4','hsk-questions/zbyhzeyaatvoyoomrjxy','[]','false',NULL,'easy',5,1,NULL,NULL,NULL,'listening'),(95,4,'true_false','Thí sinh hãy nhìn ảnh và phán đoán đúng sai ','hsk-audio/ru9ewtmgu3fw3nm42nbu','hsk-questions/qyibrrxw6ysisx6tqehq','[]','true',NULL,'easy',5,2,NULL,NULL,NULL,'listening'),(96,4,'true_false','Thí sinh hãy nhìn ảnh và phán đoán đúng sai','hsk-audio/kbku45uxh7csham9klsp','hsk-questions/b1nckzuhgj2t8spbohee','[]','true',NULL,'easy',5,3,NULL,NULL,NULL,'listening'),(97,4,'true_false','Thí sinh hãy nhìn ảnh và phán đoán đúng sai','hsk-audio/rw29xlgac7s3fug9z7cj','hsk-questions/fp7lxumylkfxhbnwskfe','[]','false',NULL,'easy',5,4,NULL,NULL,NULL,'listening'),(98,4,'true_false','Thí sinh hãy nhìn ảnh và phán đoán đúng sai','hsk-audio/uyaepbaagvscn23rl50p','hsk-questions/s1chpeqquislopebzoyw','[]','false',NULL,'easy',5,5,NULL,NULL,NULL,'listening'),(99,4,'m